import { Box, Container } from "@mui/material";
import { Outlet, useLocation } from "react-router-dom";

import DashboardHeader from "../components/layout/DashboardHeader";
import DashboardSidebar from "../components/layout/DashboardSidebar";


const pageTitles: Record<
  string,
  {
    title: string;
    subtitle: string;
  }
> = {

  "/forecast": {
    title: "Forecast",
    subtitle:
      "Generate and analyse power forecasts.",
  },


  "/model-performance": {
    title: "Model Performance",
    subtitle:
      "Monitor forecasting model performance.",
  },


  "/inference": {
    title: "Inference Monitoring",
    subtitle:
      "Monitor forecasting pipeline execution and system health.",
  },

};



const DashboardLayout = () => {


  const location = useLocation();


  const page =
    pageTitles[location.pathname] ?? {
      title: "Forecast Management",
      subtitle: "",
    };



  return (

    <Box

      sx={{

        display:"flex",

        minHeight:"100vh",

        bgcolor:"grey.100",

      }}

    >


      {/* Sidebar */}

      <DashboardSidebar />




      {/* Main Content Area */}

      <Box

        sx={{

          flex:1,

          display:"flex",

          flexDirection:"column",

          minWidth:0,

        }}

      >


        {/* Header */}

        {/* <DashboardHeader

          title={page.title}

          subtitle={page.subtitle}

        /> */}




        {/* Page Content */}

        <Box

          component="main"

          sx={{

            flex:1,

            overflow:"auto",

            py:4,

          }}

        >


          <Container

            maxWidth={false}

            sx={{

              px:{

                xs:2,

                sm:3,

                lg:4,

              },

            }}

          >


            <Outlet />


          </Container>


        </Box>


      </Box>


    </Box>

  );

};


export default DashboardLayout;
